def code_data(code):
    def item(value):
        if isinstance(value, types.CodeType):
            return {'code': code_data(value)}
        if isinstance(value, tuple):
            return {'tuple': [item(v) for v in value]}
        if isinstance(value, frozenset):
            return {'frozenset': sorted((item(v) for v in value), key=repr)}
        if isinstance(value, bytes):
            return {'bytes': value.hex()}
        if isinstance(value, float):
            return {'float': value.hex()}
        if value is Ellipsis:
            return {'ellipsis': True}
        if type(value) in (str, int, bool, type(None)):
            return value
        raise TypeError(type(value).__name__)
    return {'code': code.co_code.hex(), 'consts': [item(v) for v in code.co_consts],
            'names': list(code.co_names), 'varnames': list(code.co_varnames),
            'freevars': list(code.co_freevars), 'cellvars': list(code.co_cellvars),
            'argcount': code.co_argcount, 'posonly': code.co_posonlyargcount,
            'kwonly': code.co_kwonlyargcount, 'flags': code.co_flags,
            'exceptiontable': code.co_exceptiontable.hex()}

def code_at(code, qualified):
    for part in qualified.split('.'):
        code = next(child for child in code.co_consts
                    if isinstance(child, types.CodeType) and child.co_name == part)
    return code

def ast_at(tree, qualified):
    node = tree
    for part in qualified.split('.'):
        node = next(child for child in node.body
                    if isinstance(child, (ast.ClassDef, ast.FunctionDef)) and child.name == part)
    return node

def original_code(label, qualified):
    row = ROWS[label + ':' + qualified]
    raw = zlib.decompress(base64.b64decode(row['compressed']))
    assert hashlib.sha256(raw).hexdigest() == row['raw_sha']
    code = compile(row['prefix'].encode() + raw, '<frozen-public-numeric-original>', 'exec', dont_inherit=True)
    result = code_at(code, row['qualified'])
    assert hashlib.sha256(json.dumps(code_data(result), sort_keys=True).encode()).hexdigest() == row['code_sha']
    return result


def pe_original():
    """Full archived PE body with separately archived intensity/color suppliers."""
    from src.engine import playback_engine as pe
    from src.engine import clip_light_tracking_scope as scope
    scope_globals = dict(scope.__dict__)
    pe_globals = dict(pe.__dict__)
    for name in ('lt_intensity_params', 'lt_color_params'):
        pe_globals[name] = types.FunctionType(original_code('scope', name), scope_globals, name)
    code = original_code('pe', 'PlaybackEngine._apply_clip_light_tracking')
    assert not code.co_freevars
    return types.FunctionType(code, pe_globals, code.co_name)

def public_lt_initializer():
    from qascade_ce import lt_path
    code = original_code('lt_path', 'LtParams.__init__')
    assert not code.co_freevars
    return types.FunctionType(code, dict(lt_path.__dict__), code.co_name)

def scalar_fields(params):
    from qascade_ce.lt_path import LtParams
    result = {}
    for name in LtParams.__slots__:
        value = getattr(params, name)
        result[name] = (type(value).__name__, value.hex() if type(value) is float else value)
    return result

def verify_live_original_sources():
    from src.engine import playback_engine as pe, clip_light_tracking_scope as scope
    for label, qualified, path in (
            ('pe', 'PlaybackEngine._apply_clip_light_tracking', pe.__file__),
            ('scope', 'lt_intensity_params', scope.__file__),
            ('scope', 'lt_color_params', scope.__file__)):
        tree = ast.parse(Path(path).read_text(encoding='utf-8'))
        actual = hashlib.sha256(ast.dump(ast_at(tree, qualified), include_attributes=False).encode()).hexdigest()
        assert actual == AST_EXPECTED[label + ':' + qualified], qualified
